import { readFileSync, lstatSync, realpathSync, existsSync, mkdirSync, openSync, writeFileSync, closeSync, fsyncSync } from 'node:fs';
import { join, resolve, relative, sep, dirname } from 'node:path';
import { gunzipSync } from 'node:zlib';
import { fileURLToPath } from 'node:url';
import { assert, sha, integer, text, digest, jsonDigest, canonical, id, PROFILE_TYPES } from './model.mjs';

export function sourcePath(root,path){
  assert(typeof path==='string'&&path.length>0&&!path.includes('\\')&&!path.startsWith('/')&&!path.split('/').some(p=>!p||p==='.'||p==='..'),'SOURCE_PATH','Use an exact repository-relative source member.');
  const base=realpathSync(root),target=resolve(base,path),rel=relative(base,target);
  assert(rel!==''&&!rel.startsWith('..'+sep)&&rel!=='..'&&!rel.startsWith(sep),'SOURCE_PATH','A source member escaped its original root.');
  let here=base;for(const part of path.split('/')){here=join(here,part);assert(!lstatSync(here).isSymbolicLink(),'SOURCE_SYMLINK','An original source path contains a symbolic link.');}
  assert(lstatSync(target).isFile(),'SOURCE_FILE','Retain the complete ordinary source file: '+path);
  return target;
}
const DISTRIBUTION_SCHEMA='stellar-forge.merchant-distribution-manifest.v1';
const PRODUCT_SOURCE='stellar/scf-starforge-20261009/sf30-seller-sdk/rozo-payments';
function originalPackageMetadata(sourceRoot,manifestPath,manifest){
  if(manifest.schema!==DISTRIBUTION_SCHEMA)return null;
  const root=realpathSync(sourceRoot),directory=dirname(realpathSync(manifestPath));
  assert(directory===dirname(root)||directory===join(dirname(root),'source-package'),
    'SOURCE_PACKAGE_LOCATION','Retain the original distribution metadata beside its source.',409);
  assert(typeof manifest.sourceCommit==='string'&&/^[a-f0-9]{40}$/.test(manifest.sourceCommit)&&
    typeof manifest.packageName==='string'&&typeof manifest.packageVersion==='string'&&
    manifest.packageFiles&&canonical(Object.keys(manifest.packageFiles).sort())===canonical(['LICENSE','README.md','package.json']),
    'SOURCE_PACKAGE_MANIFEST','Retain the complete original distribution manifest.',409);
  const files=[];
  for(const path of Object.keys(manifest.packageFiles).sort()){
    const expected=manifest.packageFiles[path];sha(expected);
    const raw=readFileSync(sourcePath(directory,path));
    assert(digest(raw)===expected,'SOURCE_PACKAGE_IDENTITY','The original distribution member differs: '+path,409);
    files.push({path,bytes:raw.length,sha256:expected});
  }
  const metadata=JSON.parse(readFileSync(sourcePath(directory,'package.json')));
  assert(metadata.name===manifest.packageName&&metadata.version===manifest.packageVersion,
    'SOURCE_PACKAGE_IDENTITY','The package and original distribution manifest differ.',409);
  return {directory,files};
}
export function selectRozoSource(sourceRoot,{sourceManifest,expectedSha256,optional=false}={}){
  const root=realpathSync(sourceRoot);
  let selected=sourceManifest?resolve(sourceManifest):null;
  if(!selected){
    for(const candidate of [join(dirname(root),'manifest.json'),join(dirname(root),'source-package','manifest.json')]){
      if(!existsSync(candidate))continue;
      const raw=readFileSync(sourcePath(dirname(candidate),'manifest.json'));
      if(JSON.parse(raw).schema===DISTRIBUTION_SCHEMA){selected=candidate;break;}
    }
    const standalone=join(root,PRODUCT_SOURCE,'INSTALLED_SOURCE.json');
    if(!selected&&existsSync(standalone))selected=standalone;
  }
  if(!selected&&optional)return null;
  assert(selected,'SOURCE_MANIFEST','Select the original distribution manifest or complete standalone INSTALLED_SOURCE.json.',409);
  const identity=inspectRozoSource(root,selected,expectedSha256),manifest=realpathSync(selected);
  return {sourceRoot:root,sourceManifest:manifest,sourceIdentity:identity,
    sourcePackageDirectory:identity.packageFiles?dirname(manifest):null};
}
export function inspectRozoSourcePackage(sourceRoot,sourceManifest){
  assert(!lstatSync(sourceManifest).isSymbolicLink(),'SOURCE_SYMLINK','Use the ordinary original source manifest.');
  const raw=readFileSync(sourceManifest),manifest=JSON.parse(raw);
  return originalPackageMetadata(sourceRoot,sourceManifest,manifest);
}

export function inspectRozoSource(sourceRoot,sourceManifest,expectedSha256){
  const root=realpathSync(sourceRoot),manifestPath=realpathSync(sourceManifest);
  assert(!lstatSync(sourceManifest).isSymbolicLink(),'SOURCE_SYMLINK','Use the ordinary original source manifest.');
  const raw=readFileSync(manifestPath);if(expectedSha256){sha(expectedSha256);assert(digest(raw)===expectedSha256,'SOURCE_MANIFEST','The original installed source manifest differs.',409);}
  const manifest=JSON.parse(raw),distribution=manifest.schema===DISTRIBUTION_SCHEMA;
  assert((distribution||manifest.schema==='stellar-forge.rozo-installed-source.v1')&&Array.isArray(manifest.files)&&manifest.files.length,'SOURCE_MANIFEST','Select the complete original ROZO source declaration.',409);
  const rows=distribution?manifest.files.map(row=>({path:row.path,bytes:row.bytes,sha256:row.sha256})):manifest.files,names=new Set();let bytes=0;
  for(let index=0;index<rows.length;index++){
    const row=rows[index];assert(!names.has(row.path),'SOURCE_DUPLICATE','The installed source repeats a path.');names.add(row.path);sha(row.sha256);integer(row.bytes,'source bytes');
    if(distribution)assert(manifest.files[index].packagePath==='source/'+row.path,'SOURCE_PACKAGE_MANIFEST','The original distribution source path differs.',409);
    const path=sourcePath(root,row.path);assert(path!==manifestPath,'SOURCE_MANIFEST','The selected source manifest must exclude itself.');
    const body=readFileSync(path);assert(body.length===row.bytes&&digest(body)===row.sha256,'SOURCE_IDENTITY','The selected installed source differs: '+row.path,409);bytes+=body.length;
  }
  const packageMetadata=originalPackageMetadata(root,manifestPath,manifest);
  return {manifestSha256:digest(raw),selectionSha256:jsonDigest(rows),files:rows,fileCount:rows.length,bytes,
    ...(packageMetadata?{packageFiles:packageMetadata.files,distribution:{sourceCommit:manifest.sourceCommit,packageName:manifest.packageName,packageVersion:manifest.packageVersion}}:{})};
}
export function inspectPublisher(root,selection){
  assert(Array.isArray(selection)&&selection.length,'PUBLISHER_SELECTION','Select the complete retained publisher source.');
  const names=new Set();let bytes=0;
  for(const row of selection){assert(!names.has(row.path),'PUBLISHER_DUPLICATE','The original publisher selection repeats a path.');names.add(row.path);const body=readFileSync(sourcePath(root,row.path));assert(body.length===row.bytes&&digest(body)===row.sha256,'PUBLISHER_SOURCE','The original publisher bytes differ: '+row.path,409);bytes+=body.length;}
  return {sourceRoot:realpathSync(root),files:selection.length,bytes,sourceSelectionSha256:jsonDigest(selection)};
}
export function materializePublisher(capsuleFile,directory,{expectedSha256}={}){
  const bytes=readFileSync(capsuleFile);if(expectedSha256)assert(digest(bytes)===expectedSha256,'PUBLISHER_CAPSULE','The selected publisher capsule bytes differ.',409);
  const wrapper=JSON.parse(bytes);assert(wrapper.schema==='stellar-forge.rozo-publisher-capsule.v1'&&wrapper.encoding==='gzip+base64','PUBLISHER_CAPSULE','Select the original complete publisher capsule.');
  const compressed=Buffer.from(wrapper.data,'base64');assert(compressed.toString('base64')===wrapper.data,'PUBLISHER_CAPSULE','The publisher capsule base64 is invalid.');
  const raw=gunzipSync(compressed,{maxOutputLength:64*1024*1024});assert(raw.length===wrapper.bytes&&digest(raw)===wrapper.sha256,'PUBLISHER_CAPSULE','The full decoded publisher source differs.');
  const packet=JSON.parse(raw);assert(packet.schema==='stellar-forge.rozo-publisher-source.v1'&&Array.isArray(packet.files),'PUBLISHER_CAPSULE','The source packet is incomplete.');
  const root=resolve(directory);mkdirSync(root,{recursive:true,mode:0o700});assert(!lstatSync(root).isSymbolicLink(),'PUBLISHER_PATH','Select an ordinary source directory.');
  const marker=join(root,'ROZO_PUBLISHER_SOURCE.json'),identity={schema:'stellar-forge.rozo-publisher-binding.v1',repository:packet.repository,commit:packet.commit,packetSha256:wrapper.sha256};
  if(existsSync(marker))assert(canonical(JSON.parse(readFileSync(marker)))===canonical(identity),'PUBLISHER_IDENTITY','This directory belongs to another original publisher edition.',409);
  else{const fd=openSync(marker,'wx',0o600);try{writeFileSync(fd,canonical(identity)+'\n');fsyncSync(fd);}finally{closeSync(fd);}}
  const selection=[];
  for(const row of packet.files){
    assert(row.encoding==='utf-8'||row.encoding==='base64','PUBLISHER_ENCODING','The original source encoding is not supported.');
    assert(typeof row.path==='string'&&!row.path.startsWith('/')&&!row.path.includes('\\')&&!row.path.split('/').some(x=>!x||x==='.'||x==='..'),'SOURCE_PATH','A publisher path escapes its original directory.');
    const body=Buffer.from(row.content,row.encoding==='utf-8'?'utf8':'base64');assert(body.length===row.bytes&&digest(body)===row.sha256,'PUBLISHER_SOURCE','The original packet member differs: '+row.path);
    const file=join(root,row.path);mkdirSync(dirname(file),{recursive:true,mode:0o700});let here=root;for(const part of row.path.split('/').slice(0,-1)){here=join(here,part);assert(!lstatSync(here).isSymbolicLink(),'SOURCE_SYMLINK','A publisher directory contains a symbolic link.');}
    if(existsSync(file)){assert(lstatSync(file).isFile()&&!lstatSync(file).isSymbolicLink()&&readFileSync(file).equals(body),'PUBLISHER_SOURCE','An existing original source member differs: '+row.path,409);}
    else{const fd=openSync(file,'wx',0o600);try{writeFileSync(fd,body);fsyncSync(fd);}finally{closeSync(fd);}}
    selection.push({path:row.path,bytes:row.bytes,sha256:row.sha256});
  }
  return {...identity,...inspectPublisher(root,selection)};
}
export function loadRozoConfiguration(file){
  const stat=lstatSync(file);assert(stat.isFile()&&!stat.isSymbolicLink(),'CONFIGURATION_FILE','Use the actual host configuration file.');
  const raw=readFileSync(file),config=JSON.parse(raw);assert(config.schema==='stellar-forge.rozo-connections.v1'&&config.connections&&typeof config.connections==='object'&&!Array.isArray(config.connections),'CONFIGURATION_SCHEMA','Select the original ROZO host connections.');
  for(const [alias,c]of Object.entries(config.connections)){
    id(alias,'connection alias');assert(PROFILE_TYPES.includes(c.type)||c.type==='stellar-rpc','CONNECTION_TYPE','Select a supported original connection profile.');
    assert(!Object.hasOwn(c,'apiKey')&&!Object.hasOwn(c,'webhookSecret')&&!Object.hasOwn(c,'apiToken'),'CONFIGURATION_SECRET','Connection config retains environment variable names; keep key bytes in the original host environment.');
    for(const field of ['apiKeyEnv','webhookSecretEnv','apiTokenEnv'])if(c[field])assert(/^[A-Za-z_][A-Za-z0-9_]*$/.test(c[field]),'CONFIGURATION_ENV','Invalid environment name.');
  }
  const publisherFile=config.publisherSelectionsFile??fileURLToPath(new URL('./publishers.json',import.meta.url)),publishers=JSON.parse(readFileSync(publisherFile));
  assert(publishers.schema==='stellar-forge.rozo-publisher-selections.v1','PUBLISHER_SELECTION','The host publisher selection has another schema.');
  return {connections:config.connections,publisherSelections:Object.fromEntries(publishers.publishers.map(p=>[p.repository,p.files])),configurationIdentity:{sha256:digest(raw),bytes:raw.length,path:realpathSync(file)},config,raw};
}

import { readSync, createReadStream, mkdirSync, readFileSync, lstatSync, readdirSync, openSync, writeFileSync, closeSync, fsyncSync, existsSync, realpathSync, copyFileSync, unlinkSync, linkSync } from 'node:fs';
import { join, dirname, relative, resolve, sep } from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createHash, randomUUID } from 'node:crypto';
import { RozoWorkspace } from './store.mjs';
import { acquireLease, withLease } from './lease.mjs';
import { sourcePath, inspectPublisher, inspectRozoSource, inspectRozoSourcePackage } from './source.mjs';
import { assert, fields, id, text, canonical, digest, jsonDigest, clone } from './model.mjs';

const ROOT='stellar/scf-starforge-20261009/sf30-seller-sdk/rozo-payments';
export const DELIVERY_SCHEMA='stellar-forge.rozo-delivery.v1';
export function hashOriginalFile(path){
  const stat=lstatSync(path);assert(stat.isFile()&&!stat.isSymbolicLink(),'DELIVERY_FILE','Select an ordinary original file.');
  const fd=openSync(path,'r'),hash=createHash('sha256'),chunk=Buffer.alloc(1024*1024);let bytes=0;
  try{for(;;){const count=readSync(fd,chunk,0,chunk.length,null);if(!count)break;bytes+=count;hash.update(chunk.subarray(0,count));}}finally{closeSync(fd);}
  assert(bytes===stat.size,'DELIVERY_FILE','The original file changed while reading.',409);
  return {bytes,sha256:hash.digest('hex')};
}
export function putOriginal(path,bytes){
  const raw=Buffer.isBuffer(bytes)?bytes:Buffer.from(bytes);mkdirSync(dirname(path),{recursive:true,mode:0o700});
  const reuse=()=>{
    assert(lstatSync(path).isFile()&&!lstatSync(path).isSymbolicLink()&&readFileSync(path).equals(raw),'DELIVERY_CONFLICT','The original delivery member differs: '+path,409);
  };
  if(existsSync(path)){reuse();return;}
  const temp=path+'.rozo-write-'+randomUUID();
  const fd=openSync(temp,'wx',0o600);
  try{
    try{writeFileSync(fd,raw);fsyncSync(fd);}finally{closeSync(fd);}
    try{linkSync(temp,path);}
    catch(error){if(error.code!=='EEXIST')throw error;reuse();}
  }finally{unlinkSync(temp);}
}
function ordinaryFiles(root,prefix=''){
  const out=[];
  if(!existsSync(root))return out;
  for(const entry of readdirSync(root,{withFileTypes:true})){
    const name=prefix?prefix+'/'+entry.name:entry.name,path=join(root,entry.name),stat=lstatSync(path);
    assert(!stat.isSymbolicLink(),'DELIVERY_SYMLINK','A complete receiving source contains a symbolic link: '+name,409);
    if(stat.isDirectory())out.push(...ordinaryFiles(path,name));else{assert(stat.isFile(),'DELIVERY_FILE','Retain ordinary original files: '+name);out.push(name);}
  }return out;
}
export function originalSourceClosure(sourceRoot,manifest){
  const root=realpathSync(sourceRoot),selected=new Map(manifest.files.map(r=>[r.path,r])),queue=[...selected.keys()];
  for(let at=0;at<queue.length;at++){
    const path=queue[at];if(!/\.[cm]?js$/.test(path))continue;
    const content=readFileSync(sourcePath(root,path),'utf8');
    const references=[...content.matchAll(/(?:\bfrom\s*|\bimport\s*\(\s*|\bimport\s*|\bexport\s*[^;]*?\bfrom\s*)['"](\.[^'"]+)['"]/g)].map(m=>m[1]);
    for(const ref of references){
      const absolute=resolve(root,dirname(path),ref),p=relative(root,absolute).split(sep).join('/');
      assert(!p.startsWith('../')&&!p.startsWith('/'),'SOURCE_PATH','A relative dependency escaped the original repository.');
      if(selected.has(p))continue;
      const bytes=readFileSync(sourcePath(root,p));selected.set(p,{path:p,bytes:bytes.length,sha256:digest(bytes)});queue.push(p);
    }
  }
  return [...selected.values()].sort((a,b)=>a.path.localeCompare(b.path));
}
function addFile(stage,name,body,files){
  assert(!files.some(r=>r.path===name),'DELIVERY_DUPLICATE','A full delivery repeats a member.');
  putOriginal(join(stage,name),body);files.push({path:name,bytes:body.length,sha256:digest(body),mode:'0600'});
}
function originalRuntime(connection,kind){
  const decoder=kind==='decoder',root=connection[decoder?'decoderRuntimeRoot':'runtimeRoot'],files=connection[decoder?'decoderRuntimeFiles':'runtimeFiles'];
  assert(root&&Array.isArray(files)&&files.length,'RUNTIME_SELECTION','Complete receiving needs the original '+kind+' runtime root and every installed dependency member.',409);
  inspectPublisher(root,files);return {root:realpathSync(root),files};
}
export async function pythonArchive(args,{python=process.env.ROZO_PYTHON??'python3',signal}={}){
  const child=spawn(python,['-B',fileURLToPath(new URL('./archive.py',import.meta.url)),...args],{stdio:['ignore','pipe','pipe']});
  let output='',error='';child.stdout.on('data',c=>{if(output.length<1024*1024)output+=c;});child.stderr.on('data',c=>{if(error.length<1024*1024)error+=c;});
  const stop=()=>child.kill('SIGTERM');signal?.addEventListener('abort',stop,{once:true});
  try{const code=await new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',resolve);});assert(code===0,'ARCHIVE_FAILED','The original archive command did not complete.',500,{code,stderr:error});return JSON.parse(output);}
  finally{signal?.removeEventListener('abort',stop);}
}
export function deliveryDescriptor(workspace,deliveryId){
  id(deliveryId);const path=join(workspace.directory,'deliveries',deliveryId,'EXPORT.json');if(!existsSync(path))return null;
  const receipt=JSON.parse(readFileSync(path)),zip=join(workspace.directory,'deliveries',deliveryId,'Rozo_Workspace.zip');
  assert(receipt.deliveryId===deliveryId&&receipt.workspaceId===workspace.meta().workspaceId,'DELIVERY_IDENTITY','The retained delivery belongs to another workspace.',409);
  assert(lstatSync(zip).isFile()&&!lstatSync(zip).isSymbolicLink()&&lstatSync(zip).size===receipt.bytes,'DELIVERY_FILE','The actual retained archive size differs.');
  return {...receipt,path:zip};
}
function receivedSource(root,manifest){
  const legacy='source/'+ROOT+'/INSTALLED_SOURCE.json';
  const descriptor=manifest.sourceManifest??{path:legacy,sha256:manifest.sourceIdentity.manifestSha256};
  assert(descriptor.path===legacy||descriptor.path==='source-package/manifest.json',
    'RECEIVE_SOURCE_MANIFEST','Select the original retained source manifest.',409);
  const sourceRoot=join(root,'source'),sourceManifest=sourcePath(root,descriptor.path),raw=readFileSync(sourceManifest);
  assert(descriptor.sha256===manifest.sourceIdentity.manifestSha256&&digest(raw)===descriptor.sha256&&
    (descriptor.bytes===undefined||descriptor.bytes===raw.length),
    'RECEIVE_SOURCE_MANIFEST','The complete original source manifest bytes differ.',409);
  const identity=inspectRozoSource(sourceRoot,sourceManifest,descriptor.sha256);
  assert(canonical(identity)===canonical(manifest.sourceIdentity),
    'RECEIVE_SOURCE_IDENTITY','The complete original source and package metadata differ.',409);
  return {sourceRoot,sourceManifest};
}
export async function buildDelivery(workspace,request,{sourceRoot,sourceManifest,sourceIdentity,configuration,publisherSelections,python,signal}){
  const original=request.intent;assert(original?.deliveryId&&original.sourceSha256===sourceIdentity.manifestSha256,'DELIVERY_SOURCE','Resume with the exact original prepared application source.',409);
  const known=deliveryDescriptor(workspace,original.deliveryId);if(known)return known;
  const directory=join(workspace.directory,'deliveries',original.deliveryId),stage=join(directory,'contents');mkdirSync(stage,{recursive:true,mode:0o700});
  return withLease(workspace,'native-files',async()=>{
    const existing=join(stage,'DELIVERY.json');
    if(!existsSync(existing)){
      const files=[],selection=inspectRozoSource(sourceRoot,sourceManifest,sourceIdentity.manifestSha256),manifest=JSON.parse(readFileSync(sourceManifest));
      const sourceFiles=originalSourceClosure(sourceRoot,manifest);
      for(const row of sourceFiles){const bytes=readFileSync(sourcePath(sourceRoot,row.path));assert(bytes.length===row.bytes&&digest(bytes)===row.sha256,'SOURCE_IDENTITY','The original source changed while exporting.',409);addFile(stage,'source/'+row.path,bytes,files);}
      const packageMetadata=inspectRozoSourcePackage(sourceRoot,sourceManifest),sourceManifestPath=packageMetadata?'source-package/manifest.json':'source/'+ROOT+'/INSTALLED_SOURCE.json';
      if(packageMetadata){
        assert(sourceFiles.length===selection.files.length,'SOURCE_PACKAGE_CLOSURE','The original distribution manifest must include every source dependency.',409);
        for(const row of packageMetadata.files)addFile(stage,'source-package/'+row.path,readFileSync(sourcePath(packageMetadata.directory,row.path)),files);
      }
      const manifestBytes=readFileSync(sourceManifest);
      addFile(stage,sourceManifestPath,manifestBytes,files);
      const retainedSourceManifest={path:sourceManifestPath,bytes:manifestBytes.length,sha256:digest(manifestBytes)};
      addFile(stage,'workspace/workspace.json',readFileSync(join(workspace.directory,'workspace.json')),files);
      addFile(stage,'workspace/RECEIVING.json',Buffer.from(canonical({schema:'stellar-forge.rozo-receiving-marker.v1',mode:original.mode,deliveryId:original.deliveryId,requestId:request.id,workspaceId:workspace.meta().workspaceId,originId:workspace.meta().originId})+'\n'),files);
      for(const name of ordinaryFiles(join(workspace.directory,'cli-requests')))addFile(stage,'workspace/cli-requests/'+name,readFileSync(sourcePath(join(workspace.directory,'cli-requests'),name)),files);
      for(const name of ordinaryFiles(join(workspace.directory,'native')))addFile(stage,'workspace/native/'+name,readFileSync(sourcePath(join(workspace.directory,'native'),name)),files);
      const config=clone(configuration.config),originalConfig=configuration.raw??Buffer.from(canonical(configuration.config));
      assert(digest(originalConfig)===original.configurationSha256,'CONFIGURATION_CHANGED','Resume with the original prepared host configuration.',409);
      addFile(stage,'configuration/original.json',originalConfig,files);
      const received=clone(config),paths={};delete received.publisherSelectionsFile;
      for(const [alias,c]of Object.entries(received.connections)){
        if(c.sourceRoot){
          const selected=publisherSelections[c.publisher];assert(selected?.length,'PUBLISHER_SELECTION','Retain the complete original publisher selection.');
          inspectPublisher(c.sourceRoot,selected);const target='publishers/'+alias;
          for(const row of selected)addFile(stage,target+'/'+row.path,readFileSync(sourcePath(c.sourceRoot,row.path)),files);
          paths[alias]={sourceRoot:target};c.sourceRoot='@ROOT/'+target;
        }
        if(c.modulePath){
          const runtime=originalRuntime(c,'sdk'),prefix='runtimes/'+alias+'/sdk';
          for(const row of runtime.files)addFile(stage,prefix+'/'+row.path,readFileSync(sourcePath(runtime.root,row.path)),files);
          const member=relative(runtime.root,realpathSync(c.modulePath)).split(sep).join('/');
          assert(runtime.files.some(r=>r.path===member),'RUNTIME_ENTRY','The original SDK entry is outside its complete runtime selection.');
          c.modulePath='@ROOT/'+prefix+'/'+member;c.runtimeRoot='@ROOT/'+prefix;
        }
        if(c.decoderModule){
          const runtime=originalRuntime(c,'decoder'),prefix='runtimes/'+alias+'/decoder';
          for(const row of runtime.files)addFile(stage,prefix+'/'+row.path,readFileSync(sourcePath(runtime.root,row.path)),files);
          for(const key of ['decoderModule','decoderPackageJson']){const member=relative(runtime.root,realpathSync(c[key])).split(sep).join('/');assert(runtime.files.some(r=>r.path===member),'RUNTIME_ENTRY','The original decoder entry is outside its runtime selection.');c[key]='@ROOT/'+prefix+'/'+member;}
          c.decoderRuntimeRoot='@ROOT/'+prefix;
        }
      }
      addFile(stage,'configuration/received-template.json',Buffer.from(canonical(received)+'\n'),files);
      const database=join(stage,'workspace','rozo.sqlite3');let captured;
      if(existsSync(database)){
        const snapshot=new RozoWorkspace(join(stage,'workspace'),{readOnly:true});try{captured=snapshot.meta();assert(captured.workspaceId===workspace.meta().workspaceId,'WORKSPACE_IDENTITY','The retained checkpoint belongs to another workspace.');if(original.mode==='handover')assert(captured.revision===request.result.revision,'HANDOVER_REVISION','The sealed handover checkpoint differs from its original accepted revision.');}finally{snapshot.close();}
      }else captured=await workspace.exportDatabase(database);
      const body=hashOriginalFile(database);files.push({path:'workspace/rozo.sqlite3',...body,mode:'0600'});
      const sourceMarker=JSON.parse(readFileSync(join(stage,'workspace','workspace.json')));
      const nativeMeta=new RozoWorkspace(join(stage,'workspace'),{readOnly:true});let meta;try{meta=nativeMeta.meta();}finally{nativeMeta.close();}
      const delivery={schema:DELIVERY_SCHEMA,deliveryId:original.deliveryId,mode:original.mode,title:original.title,workspace:{...sourceMarker,revision:meta.revision},operation:{requestId:request.id,fingerprint:request.fingerprint,acceptedRevision:request.result.revision},sourceIdentity:selection,sourceManifest:retainedSourceManifest,configurationSha256:original.configurationSha256,publisherLocations:paths,files:files.sort((a,b)=>a.path.localeCompare(b.path))};
      putOriginal(existing,Buffer.from(canonical(delivery)+'\n'));
    }
    const packed=await pythonArchive(['pack','--directory',stage,'--out',join(directory,'Rozo_Workspace.zip')],{python,signal});
    const manifestRaw=readFileSync(existing),manifest=JSON.parse(manifestRaw);
    const receipt={schema:'stellar-forge.rozo-export-receipt.v1',deliveryId:original.deliveryId,workspaceId:manifest.workspace.workspaceId,originId:manifest.workspace.originId,revision:manifest.workspace.revision,mode:original.mode,requestId:request.id,bytes:packed.bytes,sha256:packed.sha256,manifestSha256:digest(manifestRaw),name:'Rozo_Workspace.zip'};
    putOriginal(join(directory,'EXPORT.json'),Buffer.from(canonical(receipt)+'\n'));return {...receipt,path:packed.path};
  });
}
export async function receiveDelivery(archive,directory,{sha256,activate=false,actor='receiving operator',requestId,python}={}){
  assert(sha256,'ARCHIVE_IDENTITY','Select the exact saved archive SHA-256.');
  const existingRoot=resolve(directory),receivedReceipt=join(existingRoot,'RECEIVED_ARCHIVE.json'),manifestFile=join(existingRoot,'DELIVERY.json');
  if(activate&&requestId&&existsSync(receivedReceipt)&&existsSync(manifestFile)){
    const custody=JSON.parse(readFileSync(receivedReceipt)),manifestRaw=readFileSync(manifestFile),m=JSON.parse(manifestRaw);
