    const transferDirectory=join(root,'runtime-transfer');
    const transferred=await exportRuntimeTransfer({runtimeDirectory,directory:transferDirectory,cache,npm,offline:true,
      expectedLockSha256:runtime.lockSha256,onProgress:event=>onProgress({phase:'runtime-transfer',...event})});
    assert(transferred.complete,'APPLICATIONS_TRANSFER','The complete original runtime transfer is not retained.',409);
    await stage('runtime-transfer',()=>Promise.resolve({transferId:transferred.manifest.transferId,manifestSha256:transferred.manifestSha256,manifest:transferred.manifest,parts:transferred.parts}));
    const transferReceive=join(root,'runtime-transfer-received'),manifestFile=join(transferDirectory,'manifest.json');
    await beginRuntimeTransferReceive({directory:transferReceive,manifest:readFileSync(manifestFile),manifestSha256:transferred.manifestSha256});
    for(const part of transferred.manifest.parts){
      const path=join(root,'transfer-parts',part.name);mkdirSync(dirname(path),{recursive:true,mode:0o700});
      await copyRuntimeTransferPart({directory:transferDirectory,index:part.index,file:path});
      checkedFile(path,part);
      await receiveRuntimeTransferPart({directory:transferReceive,index:part.index,file:path});emitArtifact({path,...hashOriginalFile(path)});
    }
    if(!progress.receivingTargets.length){progress.receivingTargets.push({directory:join(root,'received-runtime-1'),from:null});save();}
    let receiver=progress.receivingTargets.at(-1);
    if(existsSync(receiver.directory)&&!existsSync(join(receiver.directory,'runtime-install.json'))){
      receiver={directory:join(root,'received-runtime-'+(progress.receivingTargets.length+1)),from:receiver.directory};
      progress.receivingTargets.push(receiver);save();
    }
    await installReceivedRuntime({directory:transferReceive,runtimeDirectory:receiver.directory,npm,python,install:false,recoverFrom:receiver.from});
    const installedSelection=selectRozoSource(join(receiver.directory,'package','source'));
    same(installedSelection.sourceIdentity,sourceSelection.sourceIdentity,'APPLICATIONS_TRANSFER_SOURCE','The received package/source bytes changed.');
    const selection={
      schema:'stellar-forge.rozo-installed-receiving-selection.v1',operationId:APPLICATIONS_OPERATION,nativeOperation:NATIVE_OPERATION,
      nativeCompletionSha256:binding.nativeCompletionSha256,workspaceId:binding.workspaceId,originId:binding.originId,
      applicationId:progress.applicationId,applicationRevision:application.revision,applicationRunId:progress.startRequestId,
      transfer:{directory:transferReceive,transferId:transferred.manifest.transferId,manifestSha256:transferred.manifestSha256},
      runtimeDirectory:receiver.directory,recoverFrom:receiver.from,runtime,sourceIdentity:sourceSelection.sourceIdentity,
      archive:exported.archive,inventory:exported.inventory,exportRequestId:progress.exportRequest.requestId,
      directory:join(root,'received-working-workspace'),resultFile:join(root,'INSTALLED_RECEIVING_RESULT.json'),npm,python
    };
    const selectionPath=join(root,'requests','installed-receiving-'+digest(receiver.directory)+'.json');retain(selectionPath,selection);
    const executed=await nativeChild(join(installedSelection.sourceRoot,PRODUCT,'applications-receiving.mjs'),selectionPath,lease,root);
    retain(join(root,'receiving-process-'+digest(canonical(executed))+'.json'),executed);
    assert(executed.code===0,'APPLICATIONS_COLD_RECEIVER','The separate original installed receiver needs its retained continuation.',409,executed);
    const received=read(selection.resultFile);
    assert(received.selectionSha256===digest(readFileSync(selectionPath))&&received.applicationId===progress.applicationId&&received.readOnly,
      'APPLICATIONS_COLD_RECEIVER','The original cold receiver result differs.',409);
    const finalTransfer=await inspectRuntimeTransfer({directory:transferReceive,verify:true});
    assert(finalTransfer.complete&&finalTransfer.manifestSha256===transferred.manifestSha256,'APPLICATIONS_COLD_TRANSFER','The exact complete transfer was not received.',409);
    emitArtifact({path:selection.resultFile,...hashOriginalFile(selection.resultFile)});
    const result={
      schema:'stellar-forge.rozo-installed-applications-completion.v1',operationId:APPLICATIONS_OPERATION,
      nativeOperation:NATIVE_OPERATION,nativeCompletionSha256:binding.nativeCompletionSha256,dataContext:'DEVELOPMENT',
      sourceCommit:ref,sourceIdentity:sourceSelection.sourceIdentity,originalWorkspace:{workspaceId:binding.workspaceId,originId:binding.originId,
        originalRevision:initial.workspace.revision,exportRevision:read(exported.inventory.path).workspace.revision},
      built,runtime,application:{workspaceId:progress.staffWorkspaceId,directory:staffDirectory,id:progress.applicationId,
        revision:application.revision,saveRequestId:progress.saveRequestId,runId:progress.startRequestId,runs:progress.startRequests,phase:application.phase},
      browser:read(join(root,'receipts','installed-browser-'+progress.startRequestId+'.json')),working:exported.archive,
      transfer:{directory:transferDirectory,transferId:transferred.manifest.transferId,manifestSha256:transferred.manifestSha256},
      receiving:received,artifacts:progress.files,phases:Object.keys(progress.stages),
      completedAt:new Date().toISOString(),publicProviderPayments:0,transactionsSignedOrSent:0
    };
    retain(finalFile,result);progress.state='complete';progress.phase='complete';delete progress.pending;save();return {...result,directory:root};
  }catch(error){
    progress.state='pending';progress.lastError={code:error.code??'APPLICATIONS_ERROR',message:error.message,details:error.details??{},at:new Date().toISOString()};
    try{save();}catch(checkpointError){error.checkpointError={code:checkpointError.code??'CHECKPOINT_ERROR',message:checkpointError.message};}throw error;
  }finally{
    await browser?.close();await host?.close();await model?.close();
    for(const [name,value]of Object.entries(previousEnvironment))if(value===undefined)delete process.env[name];else process.env[name]=value;
    await lease.close();
  }
}

import { mkdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { assert, canonical } from './model.mjs';
import { hashOriginalFile } from './delivery.mjs';

/** Real Applications navigation over the saved application and its original run. */
export async function openInstalledRozoBrowser({
  directory, startup, application, expectedWorkspace, chromium, playwrightModule,
  onArtifact=()=>{}, onStopRequest=()=>{}
}){
  assert(chromium&&playwrightModule,'APPLICATIONS_BROWSER_RUNTIME',
    'Supply the existing Chromium executable and Playwright module.',409);
  const module=await import(pathToFileURL(playwrightModule).href),playwright=module.chromium?module:module.default;
  assert(playwright?.chromium,'APPLICATIONS_BROWSER_RUNTIME','The selected Playwright module has no Chromium export.');
  mkdirSync(directory,{recursive:true,mode:0o700});
  const browser=await playwright.chromium.launch({executablePath:chromium,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
  const context=await browser.newContext({viewport:{width:1440,height:1000},acceptDownloads:true}),page=await context.newPage(),errors=[];
  page.on('pageerror',error=>errors.push(error.message));
  let product,closed=false;
  const artifact=async(target,name)=>{
    const path=join(directory,name);
    if(!existsSync(path))await target.screenshot({path,fullPage:true});
    const value={name,path,...hashOriginalFile(path)};await onArtifact(value);return value;
  };
  const select=async()=>{
    await page.locator('button[data-view="applications"]').click();
    const selected=page.locator('#application-library-results [data-application-id="'+application.id+'"]');
    await selected.waitFor({state:'visible',timeout:30000});await selected.click();
    await page.locator('#applications-workspace').getByRole('heading',{name:application.label,exact:true}).waitFor({state:'visible'});
  };
  try{
    await page.goto(startup.url,{waitUntil:'domcontentloaded'});
    await page.locator('button[data-view="applications"]').waitFor({state:'visible'});
    await select();
    const open=page.getByRole('link',{name:'Open application',exact:true});await open.waitFor({state:'visible',timeout:30000});
    const href=await open.getAttribute('href');
    assert(href===application.current.privateUrl,'APPLICATIONS_BROWSER_BINDING','The actual Open control names another retained run.',409);
    await artifact(page,'Applications_Running.png');
    [product]=await Promise.all([context.waitForEvent('page',{timeout:30000}),open.click()]);
    product.on('pageerror',error=>errors.push(error.message));
    await product.waitForLoadState('domcontentloaded');
    await product.locator('#navigation button').first().waitFor({state:'visible',timeout:30000});
    const address=new URL(href),token=new URLSearchParams(address.hash.slice(1)).get('session');
    const observed=await product.evaluate(async token=>{
      const response=await fetch('/api/state',{headers:{'X-Rozo-Session':token}});
      return {status:response.status,value:await response.json()};
    },token);
    assert(observed.status===200&&observed.value.schema==='stellar-forge.rozo-payments-state.v1'&&
      observed.value.workspace.workspaceId===expectedWorkspace.workspaceId&&observed.value.workspace.originId===expectedWorkspace.originId,
      'APPLICATIONS_BROWSER_WORKSPACE','The installed browser did not open the same original ROZO workspace.',409);
    await artifact(product,'ROZO_Installed_Workspace.png');
    await page.setViewportSize({width:430,height:920});
    await artifact(page,'Applications_Narrow.png');
    await page.setViewportSize({width:1440,height:1000});
    assert(errors.length===0,'APPLICATIONS_BROWSER_SCRIPT','The installed staff interface raised a script error.',500,{errors});
    const receipt={schema:'stellar-forge.rozo-installed-browser.v1',applicationId:application.id,
      applicationRevision:application.revision,operationId:application.current.id,
      workspaceId:observed.value.workspace.workspaceId,originId:observed.value.workspace.originId,
      sourceIdentity:observed.value.sourceIdentity,openedOriginalControl:true};
    return {
      receipt,
      async stop(original){
        assert(original.applicationId===application.id&&original.operationId===application.current.id,
          'APPLICATIONS_STOP_IDENTITY','Stop must retain the original application run.',409);
        const route='**/api/applications/stop';
        let seen=false;
        const intercept=async request=>{
          const body=request.request().postDataJSON();
          assert(canonical(body)===canonical(original),'APPLICATIONS_STOP_IDENTITY','The Stop control changed the original run.',409);
          await onStopRequest(body);seen=true;await request.continue();
        };
        await page.route(route,intercept);
        try{
          const [accepted]=await Promise.all([
            page.waitForResponse(r=>new URL(r.url()).pathname==='/api/applications/stop'&&r.request().method()==='POST',{timeout:30000}),
            page.getByRole('button',{name:'Stop application',exact:true}).click()
          ]);
          const value=await accepted.json();
          assert(seen&&accepted.ok(),'APPLICATIONS_STOP_RESPONSE','The original Stop request requires reconciliation.',409,{status:accepted.status(),value});
          return {status:accepted.status(),value};
        }finally{await page.unroute(route,intercept);}
      },
      async stopped(){
        await page.reload({waitUntil:'domcontentloaded'});await select();
        await page.getByRole('link',{name:'Open application',exact:true}).waitFor({state:'hidden',timeout:30000});
        return artifact(page,'Applications_Stopped.png');
      },
      async close(){if(closed)return;closed=true;await browser.close();}
    };
  }catch(error){await browser.close();throw error;}
}

#!/usr/bin/env node
import { readFileSync, realpathSync, existsSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { installReceivedRuntime, inspectRuntimeTransfer } from '../../distribution/runtime-transfer.mjs';
import { inspectRuntimeInstall } from '../../distribution/runtime-install.mjs';
import { inspectMerchantRuntime } from '../../sf46-release/runtime-package.mjs';
import { selectRozoSource } from './source.mjs';
import { RozoWorkspace } from './store.mjs';
import { receiveDelivery, putOriginal, hashOriginalFile } from './delivery.mjs';
import { nativeInventory, compareNativeInventory } from './native-inventory.mjs';
import { assert, canonical, digest } from './model.mjs';

const PRODUCT='stellar/scf-starforge-20261009/sf30-seller-sdk/rozo-payments';
function document(path){return JSON.parse(readFileSync(path));}
function exact(path,expected){
  const actual=hashOriginalFile(path);
  assert(actual.bytes===expected.bytes&&actual.sha256===expected.sha256,
    'INSTALLED_RECEIVE_FILE','The complete original receiving member differs: '+path,409);
  return actual;
}
/** Called from the received runtime's own complete source in a separate Node process. */
export async function receiveInstalledRozo(selectionFile){
  const raw=readFileSync(selectionFile),selection=JSON.parse(raw);
  assert(selection.schema==='stellar-forge.rozo-installed-receiving-selection.v1'&&
    selection.nativeOperation==='ROZO-MERCHANT-SETTLEMENT-COMMISSIONING-20261012',
    'INSTALLED_RECEIVE_SELECTION','Select the retained original installed receiving request.',409);
  const runtimeDirectory=realpathSync(selection.runtimeDirectory);
  const selected=selectRozoSource(join(runtimeDirectory,'package','source'));
  assert(selected.sourceIdentity.manifestSha256===selection.sourceIdentity.manifestSha256&&
    canonical(selected.sourceIdentity)===canonical(selection.sourceIdentity),
    'INSTALLED_RECEIVE_SOURCE','The received original runtime source differs.',409);
  const self=join(selected.sourceRoot,PRODUCT,'applications-receiving.mjs');
  assert(realpathSync(self)===realpathSync(fileURLToPath(import.meta.url)),
    'INSTALLED_RECEIVE_PROCESS','Run the receiving module from the extracted original runtime source.',409);
  const transfer=await inspectRuntimeTransfer({directory:selection.transfer.directory,verify:true});
  assert(transfer.complete&&transfer.manifestSha256===selection.transfer.manifestSha256&&
    transfer.manifest.transferId===selection.transfer.transferId,
    'INSTALLED_RECEIVE_TRANSFER','The complete original runtime transfer differs.',409);
  const installed=await installReceivedRuntime({
    directory:selection.transfer.directory,runtimeDirectory,npm:selection.npm,python:selection.python,
    install:true,recoverFrom:selection.recoverFrom??null
  });
  const inspection=await inspectRuntimeInstall({directory:runtimeDirectory,source:true,load:true,python:selection.python});
  assert(installed.status==='READY'&&inspection.status==='READY'&&inspection.ready,
    'INSTALLED_RECEIVE_READY','The received original runtime did not finish installation.',409);
  const runtime=await inspectMerchantRuntime(runtimeDirectory,{load:true});
  for(const key of ['installationId','profileId','profileSha256','lockSha256','sourceCommit','sourceManifestSha256'])
    assert(runtime[key]===selection.runtime[key],'INSTALLED_RECEIVE_RUNTIME','The original runtime identity differs: '+key,409);
  exact(selection.archive.path,selection.archive);
  exact(selection.inventory.path,selection.inventory);
  const expected=document(selection.inventory.path);
  assert(expected.workspace.workspaceId===selection.workspaceId&&expected.workspace.originId===selection.originId,
    'INSTALLED_RECEIVE_WORKSPACE','The retained original inventory belongs to another workspace.',409);
  const received=await receiveDelivery(selection.archive.path,selection.directory,{
    sha256:selection.archive.sha256,activate:false,python:selection.python
  });
  const manifest=document(join(received.directory,'DELIVERY.json'));
  assert(manifest.mode==='working'&&manifest.operation.requestId===selection.exportRequestId&&
    manifest.sourceIdentity.manifestSha256===selected.sourceIdentity.manifestSha256,
    'INSTALLED_RECEIVE_DELIVERY','The working archive does not retain the same installed source and original request.',409);
  const original=new RozoWorkspace(received.workspaceDirectory,{readOnly:true});let verified,actual,exportRequest;
  try{
    actual=nativeInventory(original);verified=compareNativeInventory(expected,actual);
    exportRequest=original.request(selection.exportRequestId);
    assert(exportRequest?.state==='accepted'&&exportRequest.envelope.command==='workspace.export'&&
      exportRequest.intent.sourceSha256===selected.sourceIdentity.manifestSha256,
      'INSTALLED_RECEIVE_REQUEST','The original working export request is not retained.',409);
  }finally{original.close();}
  let readOnly=false;
  try{const invalid=new RozoWorkspace(received.workspaceDirectory);invalid.close();}
  catch(error){readOnly=error.code==='RECEIVE_REQUIRED';}
  assert(readOnly,'INSTALLED_RECEIVE_CUSTODY','A working snapshot must remain read-only.',409);
  const result={
    schema:'stellar-forge.rozo-installed-receiving-result.v1',
    operationId:selection.operationId,nativeOperation:selection.nativeOperation,nativeCompletionSha256:selection.nativeCompletionSha256,
    dataContext:'DEVELOPMENT',selectionSha256:digest(raw),runtime,transfer:{id:transfer.manifest.transferId,manifestSha256:transfer.manifestSha256},
    workspace:verified,archive:selection.archive,exportRequestId:selection.exportRequestId,exportFingerprint:exportRequest.fingerprint,
    sourceRoot:received.sourceRoot,sourceManifest:received.sourceManifest,sourceIdentity:selected.sourceIdentity,
    workspaceDirectory:received.workspaceDirectory,configuration:received.configuration,
    readOnly:true,applicationId:selection.applicationId,applicationRevision:selection.applicationRevision,applicationRunId:selection.applicationRunId
  };
  const out=resolve(selection.resultFile);
  if(existsSync(out))assert(canonical(document(out))===canonical(result),'INSTALLED_RECEIVE_RESULT','The accepted original receiving result differs.',409);
  else putOriginal(out,Buffer.from(canonical(result)+'\n'));
